// Create this file: src/app/api/auth/register/route.ts
import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/prisma'; // Assuming your Prisma client instance is exported from here
import bcrypt from 'bcryptjs'; // For password hashing
import { z } from 'zod'; // For input validation

// Define the expected request body schema using Zod
const registerUserSchema = z.object({
    name: z.string().min(2, { message: "Name must be at least 2 characters long." }).max(100),
    email: z.string().email({ message: "Invalid email address." }),
    password: z.string().min(8, { message: "Password must be at least 8 characters long." }),
    // tenantSubdomain: z.string(), // From request body, but we primarily use the header
});

export async function POST(request: NextRequest) {
    try {
        // 1. Get Tenant ID from middleware header
        const tenantSubdomainFromHeader = request.headers.get('x-tenant-id');

        if (!tenantSubdomainFromHeader) {
            return NextResponse.json(
                { success: false, message: "Tenant information is missing. Registration cannot proceed." },
                { status: 400 }
            );
        }

        // 2. Parse and validate request body
        let body;
        try {
            body = await request.json();
        } catch (error) {
            return NextResponse.json({ success: false, message: "Invalid JSON body." }, { status: 400 });
        }

        const validationResult = registerUserSchema.safeParse(body);
        if (!validationResult.success) {
            return NextResponse.json(
                {
                    success: false,
                    message: "Validation failed.",
                    errors: validationResult.error.flatten().fieldErrors,
                },
                { status: 400 }
            );
        }

        const { name, email, password } = validationResult.data;

        // 3. Find the Tenant in the database using the subdomain from the header
        const tenant = await prisma.tenant.findUnique({
            where: { subdomain: tenantSubdomainFromHeader },
        });

        if (!tenant) {
            return NextResponse.json(
                { success: false, message: `Organization '${tenantSubdomainFromHeader}' not found. Cannot register.` },
                { status: 404 } // Not Found
            );
        }

        // 4. Check if user already exists for this tenant
        const existingUser = await prisma.user.findUnique({
            where: {
                tenantId_email: { // Using the @@unique([tenantId, email]) compound index
                    tenantId: tenant.id,
                    email: email.toLowerCase(), // Store and check emails in lowercase
                },
            },
        });

        if (existingUser) {
            return NextResponse.json(
                { success: false, message: "User with this email already exists for this organization." },
                { status: 409 } // Conflict
            );
        }

        // 5. Hash the password
        const saltRounds = 10; // Or 12 for more security
        const hashedPassword = await bcrypt.hash(password, saltRounds);

        // 6. Create the new user
        // For simplicity, new users get a default role. You might want to make this configurable.
        const defaultUserRole = "member"; // Example role

        const newUser = await prisma.user.create({
            data: {
                name,
                email: email.toLowerCase(),
                password: hashedPassword,
                role: defaultUserRole,
                tenantId: tenant.id, // Link to the found tenant
                // phoneNumber can be added here if collected from form
            },
            // Select only non-sensitive fields to return (optional)
            select: {
                id: true,
                email: true,
                name: true,
                role: true,
                tenantId: true
            }
        });

        // 7. Return success response
        // You might want to send a verification email here in a real application
        return NextResponse.json(
            {
                success: true,
                message: "Account created successfully! Please proceed to login.",
                user: { id: newUser.id, email: newUser.email, name: newUser.name }, // Don't return password
                redirectTo: `/login` // Suggest redirect to login page on the same tenant subdomain
            },
            { status: 201 } // Created
        );

    } catch (error) {
        console.error("Registration API Error:", error);
        // Log the error for debugging
        // In a real app, use a more sophisticated error logging service

        if (error instanceof z.ZodError) { // Should be caught by safeParse, but as a fallback
             return NextResponse.json(
                { success: false, message: "Invalid input data.", errors: error.flatten().fieldErrors },
                { status: 400 }
            );
        }

        return NextResponse.json(
            { success: false, message: "An unexpected internal server error occurred." },
            { status: 500 }
        );
    }
}